ection></div><script>let golpoochAnswer=Math.random()<.5?'left':'right';const gpPanel=document.getElementById('golpoochLoginPanel'),gpScene=document.querySelector('.golpooch-scene'),gpPhoto=document.querySelector('.golpooch-photo'),gpHands=[...document.querySelectorAll('.golpooch-hand')];let lastHand=null;function openGolpooch(focus=true){gpPanel.classList.remove('hidden');document.getElementById('loginScreen').classList.add('p16-login-open');gpHands.forEach(b=>b.tabIndex=-1);if(focus)gpPanel.querySelector('.golpooch-close').focus()}function pickGolpooch(hand){if(hand!==golpoochAnswer)return;lastHand=hand;openGolpooch()}function resetGolpooch(){golpoochAnswer=Math.random()<.5?'left':'right';gpPanel.classList.add('hidden');document.getElementById('loginScreen').classList.remove('p16-login-open');gpHands.forEach(b=>b.tabIndex=0);if(lastHand)gpHands.find(b=>b.classList.contains(lastHand))?.focus({preventScroll:true})}document.getElementById('p16ShowPassword').addEventListener('click',function(){const p=document.getElementById('p16LoginPassword'),show=p.type==='password';p.type=show?'text':'password';this.setAttribute('aria-pressed',String(show));this.setAttribute('aria-label',show?'پنهان کردن رمز عبور':'نمایش رمز عبور')});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!gpPanel.classList.contains('hidden'))resetGolpooch()});function fitHands(){const w=gpScene.clientWidth,h=gpScene.clientHeight,nw=gpPhoto.naturalWidth,nh=gpPhoto.naturalHeight;if(!w||!h||!nw||!nh)return;const mobile=matchMedia('(max-width:700px)').matches,rw=mobile?709:1649,rh=mobile?1204:795,z=mobile?1.2:1,shift=mobile?-.08:0,refScale=Math.max(rw/nw,rh/nh)*z,scale=Math.max(w/nw,h/nh)*z;const centers=mobile?[[.398,.516],[.624,.516]]:[[.493,.473],[.623,.473]];gpHands.forEach((b,i)=>{const cx=(centers[i][0]-.5)*rw/refScale,cy=(centers[i][1]-.5-shift)*rh/refScale;const bw=Math.max(44,Math.min(w*.30,(mobile?rw*.19:rw*.085)*scale/refScale)),bh=Math.max(44,Math.min(h*.26,(mobile?rh*.125:rh*.125)*scale/refScale));b.style.setProperty('left',(w/2+cx*scale-bw/2)+'px','important');b.style.setProperty('top',(h/2+shift*h+cy*scale-bh/2)+'px','important');b.style.setProperty('width',bw+'px','important');b.style.setProperty('height',bh+'px','important')})}gpPhoto.addEventListener('load',fitHands);window.addEventListener('resize',fitHands);fitHands();if(gpPanel.querySelector('.notice'))openGolpooch(false);</script>
