const REPORT_THEME=<?=json_encode(['recv'=>SettingsService::themeFill($uiSettings['theme_recv'],$uiSettings),'pay'=>SettingsService::themeFill($uiSettings['theme_pay'],$uiSettings),'comm'=>SettingsService::themeFill($uiSettings['theme_comm'],$uiSettings),'siteWin'=>SettingsService::themeFill($uiSettings['theme_site_win']??$uiSettings['theme_pay'],$uiSettings),'siteLoss'=>SettingsService::themeFill($uiSettings['theme_site_loss']??$uiSettings['theme_recv'],$uiSettings)],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;const REPORT_DEFAULT_TOTALS=<?=json_encode($reportData['totals'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;const REPORT_FACTOR=<?=json_encode(SettingsService::scaleFactor($uiSettings))?>;const REPORT_LOCALE=<?=json_encode($uiSettings['digit_mode']==='fa'?'fa-IR':'en-US')?>;const REPORT_UNIT=<?=json_encode(SettingsService::moneyUnit($uiSettings),JSON_UNESCAPED_UNICODE)?>;const REPORT_IS_EXPENSE_HISTORY=<?=json_encode($reportData['type']==='expense_history')?>;const REPORT_EXPENSE_TOTAL=<?=json_encode(isset($reportData['expense_total'])?TransferService::formatToman($reportData['expense_total'],$uiSettings):'0',JSON_HEX_TAG|JSON_UNESCAPED_UNICODE)?>;const REPORT_IS_TRANSFER_HISTORY=<?=json_encode($reportData['type']==='transfer_history')?>;const REPORT_TRANSFER_TOTALS=<?=json_encode($reportData['transfer_totals']??[],JSON_HEX_TAG|JSON_UNESCAPED_UNICODE)?>;const REPORT_TRANSFER_FMT=<?=json_encode(isset($reportData['transfer_totals'])?['paid'=>TransferService::formatToman($reportData['transfer_totals']['paid'],$uiSettings),'received'=>TransferService::formatToman($reportData['transfer_totals']['received'],$uiSettings)]:[],JSON_HEX_TAG|JSON_UNESCAPED_UNICODE)?>;const REPORT_IS_CUMULATIVE=<?=json_encode($rf['type']==='cumulative')?>;const REPORT_IMAGE_WIDTHS=<?=json_encode(in_array($reportData['type'],['detail','customer_detail'],true)?[56,262,182,130,152,154,154]:[])?>;const REPORT_IMAGE_TITLE=<?=json_encode(ReportingService::title($reportData),JSON_UNE