 html+='<g id="p17Cursor" pointer-events="none"></g>';svg.innerHTML=html;frame={dates,labels,series,x,y,L,R,T,H,B,W};
 legend.innerHTML=series.map((sr,i)=>'<span class="p17-series"><i style="background:'+sr.color+'"></i><b>'+esc(sr.name)+'</b><span dir="ltr">'+esc(money(sr.total))+'</span>'+(i?'<button type="button" data-remove="'+esc(sr.name)+'" aria-label="حذف '+esc(sr.name)+' از مقایسه">×</button>':'')+'</span>').join('');
 document.getElementById('p17AxisNote').textContent=(mode==='daily'?'نتیجه روزانه':'نتیجه تجمعی')+' ('+unit+') · ه: هزار، م: میلیون، م‌م: میلیارد';
 drawCursor(cursor===null?dates.length-1:Math.min(cursor,dates.length-1),false);
 }
 function drawCursor(i,mark=true){if(!frame)return;const {dates,labels,series,x,y,T,H,B}=frame;cursor=Math.max(0,Math.min(i,dates.length-1));readout.innerHTML='<b>'+esc(labels.get(dates[cursor]))+'</b>'+series.map(sr=>'<span><i style="background:'+sr.color+'"></i>'+esc(sr.name)+': <strong>'+esc(money(sr.values[cursor]))+'</strong> '+esc(unit)+'</span>').join('');const g=document.getElementById('p17Cursor');if(g)g.innerHTML=mark?'<line x1="'+x(cursor)+'" x2="'+x(cursor)+'" y1="'+T+'" y2="'+(H-B)+'" stroke="#81749e" stroke-dasharray="4 4"/>'+series.map(sr=>'<circle cx="'+x(cursor)+'" cy="'+y(sr.values[cursor])+'" r="4" fill="'+sr.color+'" stroke="white" stroke-width="1.5"/>').join(''):''}
 function pointer(e){if(!frame)return;const r=svg.getBoundingClientRect(),px=(e.clientX-r.left)*frame.W/r.width;const i=frame.dates.length===1?0:Math.round((px-frame.L)/(frame.W-frame.L-frame.R)*(frame.dates.length-1));drawCursor(i)}
 svg.addEventListener('pointermove',e=>{if(e.pointerType==='mouse'||e.buttons)pointer(e)});svg.addEventListener('pointerdown',pointer);svg.addEventListener('pointerleave',e=>{if(e.pointerType==='mouse')drawCursor(cursor,false)});svg.addEventListener('keydown',e=>{if(!frame||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();drawCursor(e.key==='Home'?0:e.key==='End'?frame.dates.length-1:cursor+(e.key==='ArrowRight'?1:-1))});
 picker.addEventListener('change',()=>{if(picker.value){selected.add(picker.value);render()}});reset.addEventListener('click',()=>{selected.clear();render()});legend.addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(b){selected.delete(b.dataset.remove);render()}});buttons.forEach(b=>b.addEventListener('click',()=>{days=Number(b.dataset.days)||30;cursor=null;render()}));modes.forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.chartMode;cursor=null;render()}));let resize;window.addEventListener('resize',()=>{clearTimeout(resize);resize=setTimeout(()=>{if(svg.isConnected)render()},100)},{signal:window.p20PageSignal});render();
})();
(function(){
 const clean=v=>String(v??'').replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/,/g,'').trim();
 const fmt=v=>{const s=clean(v);if(!s||!/^[-+]?\d*(?:\.\d*)?$/.test(s))return v;const parts=s.split('.'),sign=parts[0].startsWith('-')?'-':'';let whole=parts[0].replace(/^[-+]/,'');whole=whole.replace(/^0+(?=\d)/,'')||'0';whole=whole.replace(/\B(?=(\d{3})+(?!\d))/g,',');return sign+whole+(parts.length>1?'.'+parts[1]:'')};
 document.querySelectorAll('input.grouped-number').forEach(el=>{el.value=fmt(el.value);el.addEventListener('input',()=>{const pos=el.selectionStart,end=el.selectionEnd,before=el.value;el.value=fmt(el.value);if(pos!==null){const delta=el.value.length-before.length;try{el.setSelectionRange(Math.max(0,pos+delta),Math.max(0,(end??pos)+delta))}catch(e){}}});});
})();
};window.p20InitPageEnd();
