<script>if('serviceWorker' in navigator){window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}))}let deferredPwaPrompt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredPwaPrompt=e;document.getElementById('pwaInstallBtn')?.classList.remove('hidden')});document.addEventListener('click',async e=>{if(e.target.closest?.('#pwaInstallBtn')&&deferredPwaPrompt){deferredPwaPrompt.prompt();await deferredPwaPrompt.userChoice;deferredPwaPrompt=null;document.getElementById('pwaInstallBtn')?.classList.add('hidden')}});</script><?php if($page==='settings'):?><script>(()=>{const f=document.getElementById('financial-preferences');if(!f)return;const names=['theme_recv','theme_pay','theme_comm','theme_site_win','theme_site_loss'],swatches=[...f.querySelectorAll('.preview-swatches span')],availability=<?=json_encode($fontStatus)?>;const update=()=>{const opacity=Number(f.elements.theme_opacity.value);document.getElementById('dev15Opacity').textContent=opacity+'%';swatches.forEach((el,i)=>{const hex=f.elements[names[i]].value;const n=parseInt(hex.slice(1),16);el.style.setProperty('background-color','rgba('+[(n>>16)&255,(n>>8)&255,n&255,opacity/100].join(',')+')','important')});const fonts={vazirmatn:'Vazirmatn,Tahoma,sans-serif',iransans:'IRANSansLocal,Vazirmatn,Tahoma,sans-serif',system:'Tahoma,Arial,sans-serif'};const prev=document.getElementById('dev15FontPreview'),choice=f.elements.font_global.value;prev.style.fontFamily=fonts[choice];prev.querySelector('b').style.fontFamily=fonts[f.elements.font_heading.value];document.getElementById('dev15FontState').textContent=choice==='iransans'&&!availability.IRANSans||choice==='vazirmatn'&&!availability['Vazirmatn 400']?'فایل فونت انتخابی موجود نیست؛ نمونه با فونت جایگزین است.':''};f.addEventListener('input',update);f.addEventListener('change',update);update()})();</script><?php endif;?></body></html>
